{"explanation":"A secant line cuts a curve at two points, P at x = a and Q at x = a + h, and its slope is the difference quotient (f(a+h) − f(a))/h. As h shrinks toward 0, Q slides along the curve toward P and the secant line rotates into the tangent line — the line that just kisses the curve at P. The limiting slope is the derivative f′(a) = lim(h→0) [f(a+h) − f(a)]/h. Drag the yellow point anywhere along the parabola, shrink h with the slider (or press the animate button), and watch the orange secant settle onto the green true tangent as their slopes merge.","manimCode":"const f = function(x) { return 0.3 * x * x; };
const df = function(x) { return 0.6 * x; };

const axes = new Axes({ xRange: [-4, 4, 1], yRange: [-1, 5, 1], xLength: 8, yLength: 5, tips: false });
axes.moveTo([-2.6, -0.4, 0]);

const curve = axes.plot(f, { color: BLUE, xRange: [-3.9, 3.9], numSamples: 200 });

const curveLabel = new MathTex({ latex: 'f(x) = 0.3x^2', color: BLUE });
await curveLabel.waitForRender();
curveLabel.scale(0.8);
curveLabel.moveTo([-4.6, 1.75, 0]);

const title = new MathTex({ latex: "f'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}" });
await title.waitForRender();
title.scale(0.85);
title.moveTo([4.2, 3.0, 0]);

let a = 1;
let h = 2;
let showTangent = false;
function hEff() { return Math.min(h, 3.8 - a); }

const dotP = new Dot({ point: axes.c2p(a, f(a)), color: YELLOW });
const dotQ = new Dot({ point: axes.c2p(a + hEff(), f(a + hEff())), color: RED });

const secant = new Polygon({ vertices: [[0, 0, 0], [1, 0, 0]], color: ORANGE });
secant.setStrokeWidth(4).setFillOpacity(0);
const tangent = new Polygon({ vertices: [[0, 0, 0], [1, 0, 0]], color: GREEN });
tangent.setStrokeWidth(4).setFillOpacity(0);
const runSeg = new Polygon({ vertices: [[0, 0, 0], [1, 0, 0]], color: YELLOW });
runSeg.setStrokeWidth(2).setFillOpacity(0);
const riseSeg = new Polygon({ vertices: [[0, 0, 0], [1, 0, 0]], color: RED });
riseSeg.setStrokeWidth(2).setFillOpacity(0);

const YMIN = -0.9;
const YMAX = 4.9;
function clippedLine(x0, y0, m) {
  const xA = -3.95, xB = 3.95;
  const cand = [[xA, y0 + m * (xA - x0)], [xB, y0 + m * (xB - x0)]];
  if (Math.abs(m) > 1e-9) {
    cand.push([x0 + (YMIN - y0) / m, YMIN]);
    cand.push([x0 + (YMAX - y0) / m, YMAX]);
  }
  const inside = cand.filter(function(p) {
    return p[0] >= xA - 1e-9 && p[0] <= xB + 1e-9 && p[1] >= YMIN - 1e-6 && p[1] <= YMAX + 1e-6;
  });
  inside.sort(function(p, q) { return p[0] - q[0]; });
  return [inside[0], inside[inside.length - 1]];
}

function updateGeometry() {
  const he = hEff();
  const m = (f(a + he) - f(a)) / he;
  dotQ.moveTo(axes.c2p(a + he, f(a + he)));
  const s = clippedLine(a, f(a), m);
  secant.setVertices([axes.c2p(s[0][0], s[0][1]), axes.c2p(s[1][0], s[1][1])]);
  runSeg.setVertices([axes.c2p(a, f(a)), axes.c2p(a + he, f(a))]);
  riseSeg.setVertices([axes.c2p(a + he, f(a)), axes.c2p(a + he, f(a + he))]);
  const t = clippedLine(a, f(a), df(a));
  tangent.setVertices([axes.c2p(t[0][0], t[0][1]), axes.c2p(t[1][0], t[1][1])]);
}
dotQ.addUpdater(updateGeometry);

let hText = null, slopeText = null, trueText = null;
function updateReadout() {
  const he = hEff();
  const m = (f(a + he) - f(a)) / he;
  if (hText) scene.remove(hText);
  hText = new Text({ text: 'h = ' + he.toFixed(2), color: WHITE, fontSize: 26 });
  hText.moveTo([4.2, 2.2, 0]);
  scene.add(hText);
  if (slopeText) scene.remove(slopeText);
  slopeText = new Text({ text: 'secant slope = ' + m.toFixed(3), color: he < 0.06 ? GREEN : ORANGE, fontSize: 26 });
  slopeText.moveTo([4.2, 1.65, 0]);
  scene.add(slopeText);
  if (trueText) { scene.remove(trueText); trueText = null; }
  if (showTangent) {
    trueText = new Text({ text: "true f'(a) = " + df(a).toFixed(3), color: GREEN, fontSize: 26 });
    trueText.moveTo([4.2, 1.1, 0]);
    scene.add(trueText);
  }
}

const hint = new Text({ text: 'Drag the yellow point along the curve', color: GRAY, fontSize: 20 });
hint.moveTo([4.2, 0.5, 0]);

await scene.play(new Create(axes));
await scene.play(new AnimationGroup([new Create(curve), new Write(curveLabel)]));
await scene.play(new Write(title));
scene.add(hint);
updateGeometry();
await scene.play(new AnimationGroup([
  new FadeIn(dotP),
  new FadeIn(dotQ),
  new Create(secant),
  new Create(runSeg),
  new Create(riseSeg)
]));
updateReadout();

makeDraggable(dotP, scene, {
  constrainX: [-6.0, 0.8],
  onDrag: function(mob, pos) {
    a = Math.max(-3.4, Math.min(3.4, pos[0] + 2.6));
    mob.moveTo(axes.c2p(a, f(a)));
    updateReadout();
  }
});
makeHoverable(dotP, scene, { hoverScale: 1.5 });

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({ label: 'h', min: 0.02, max: 2.5, value: 2, step: 0.01, onChange: function(v) { h = v; updateReadout(); } });
controls.addCheckbox({ label: 'Show true tangent', checked: false, onChange: function(c) {
  showTangent = c;
  if (c) { scene.add(tangent); } else { scene.remove(tangent); }
  updateReadout();
}});
controls.addButton({ label: 'Animate h → 0', onClick: async function() {
  let v = h;
  while (v > 0.025) {
    v = Math.max(0.02, v * 0.8);
    h = v;
    updateReadout();
    await scene.wait(0.07);
  }
}});

await scene.wait(999999);"}

